-- WorkTrack synthetic demo data: 100 employees, 5 facilities, 26-28 October 2026.
-- All names/addresses are fictional. DATETIME stored UTC (Vietnam display = UTC+7).
-- Run using Execute SQL Script (DBeaver Alt+X), on the EMPTY 10-table schema.
-- Requires CREATE ROUTINE/EXECUTE/ALTER ROUTINE for the temporary import procedure.
-- No DROP/TRUNCATE of data, no FK bypass. Refuses nonempty tables, rolls back on error.
-- Demo accounts have UNUSABLE passwords; set passwords through Django before testing login.
-- Historical QR hashes are fixtures, not live QR tokens. Fresh QR must be issued by backend.
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
SET SESSION time_zone = '+00:00';
DELIMITER $$
CREATE PROCEDURE worktrack_load_demo_seed()
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
    START TRANSACTION;
    IF EXISTS (SELECT 1 FROM facilities LIMIT 1) OR
       EXISTS (SELECT 1 FROM employees LIMIT 1) OR
       EXISTS (SELECT 1 FROM users LIMIT 1) OR
       EXISTS (SELECT 1 FROM work_schedules LIMIT 1) OR
       EXISTS (SELECT 1 FROM support_assignments LIMIT 1) OR
       EXISTS (SELECT 1 FROM qr_challenges LIMIT 1) OR
       EXISTS (SELECT 1 FROM attendance_alerts LIMIT 1) OR
       EXISTS (SELECT 1 FROM attendance_scans LIMIT 1) OR
       EXISTS (SELECT 1 FROM attendance_requests LIMIT 1) OR
       EXISTS (SELECT 1 FROM audit_logs LIMIT 1) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Seed requires all 10 tables empty. Use a fresh demo database; existing data is preserved.';
    END IF;

    -- facilities: 5 rows

    -- employees: 100 rows

    -- users: 102 rows

    -- work_schedules: 300 rows

    -- support_assignments: 26 rows

    -- qr_challenges: 3 rows

    -- attendance_alerts: 10 rows

    -- attendance_scans: 635 rows

    -- attendance_requests: 30 rows

    -- audit_logs: 25 rows

    COMMIT;
END$$
DELIMITER ;
CALL worktrack_load_demo_seed();
DROP PROCEDURE worktrack_load_demo_seed;


-- Counts after successful import.
SELECT 'facilities' AS table_name, COUNT(*) AS row_count FROM facilities
UNION ALL
SELECT 'employees' AS table_name, COUNT(*) AS row_count FROM employees
UNION ALL
SELECT 'users' AS table_name, COUNT(*) AS row_count FROM users
UNION ALL
SELECT 'work_schedules' AS table_name, COUNT(*) AS row_count FROM work_schedules
UNION ALL
SELECT 'support_assignments' AS table_name, COUNT(*) AS row_count FROM support_assignments
UNION ALL
SELECT 'qr_challenges' AS table_name, COUNT(*) AS row_count FROM qr_challenges
UNION ALL
SELECT 'attendance_alerts' AS table_name, COUNT(*) AS row_count FROM attendance_alerts
UNION ALL
SELECT 'attendance_scans' AS table_name, COUNT(*) AS row_count FROM attendance_scans
UNION ALL
SELECT 'attendance_requests' AS table_name, COUNT(*) AS row_count FROM attendance_requests
UNION ALL
SELECT 'audit_logs' AS table_name, COUNT(*) AS row_count FROM audit_logs;
